def digital_root_base(n, b):
    while n >= b:
        total = 0
        x = n
        while x > 0:
            total += x % b
            x //= b
        n = total
    return n

def left_truncate_path(path, maxlen):
    if len(path) <= maxlen:
        return path
    keep_len = maxlen - 3
    if keep_len <= 0:
        return path[len(path) - maxlen:]
    return "..." + path[len(path) - keep_len:]

