def nth_ugly_number(n):
    ugly = [1]
    pointers = [0, 0, 0]
    factors = [2, 3, 5]
    while len(ugly) < n:
        candidates = [ugly[pointers[i]] * factors[i] for i in range(3)]
        nxt = min(candidates)
        ugly.append(nxt)
        for i in range(3):
            if candidates[i] == nxt:
                pointers[i] += 1
    return ugly[n - 1]

